import sys, re, zlib

def load(fname):
    data = open(fname, 'rb').read()
    return data

def object_offsets(data):
    objs = {}
    for m in re.finditer(rb'(\d+) 0 obj\b', data):
        n = int(m.group(1))
        if n not in objs:
            objs[n] = m.end()
    return objs

def obj_slice(data, start):
    # capture until matching endobj, but fallback: use regex from start
    end = data.find(b'endobj', start)
    return data[start:end if end != -1 else len(data)]

def get_stream(body, data, start):
    m = re.search(rb'stream\r?\n', body)
    if not m:
        return None
    sstart = m.end() + (data.find(b'stream\r\n', 0) - data.find(b'stream\r\n', 0))  # offset accounting done in caller
    return None

def stream_from(data, objstart):
    # stream begins after 'stream\r\n' within the object body, ends at matching endstream
    b = data.find(b'stream\n', objstart)
    b2 = data.find(b'stream\r\n', objstart)
    if b2 != -1 and (b == -1 or b2 + 8 > b):
        sstart = b2 + 8
    elif b != -1:
        sstart = b + 7
    else:
        return None
    send = data.find(b'endstream', sstart)
    raw = data[sstart:send]
    try:
        return zlib.decompress(raw)
    except Exception:
        raw2 = raw.rstrip(b'\r\n')
        try:
            return zlib.decompress(raw2)
        except Exception:
            return raw

def parse_cmap(content):
    cmap = {}
    for mm in re.finditer(rb'beginbfchar(.*?)endbfchar', content, re.S):
        for bm in re.finditer(rb'<([0-9A-Fa-f]{4})>\s*<([0-9A-Fa-f]+)>', mm.group(1)):
            src = int(bm.group(1), 16)
            b = bytes.fromhex(bm.group(2).decode())
            try:
                cmap[src] = b.decode('utf-16-be')
            except Exception:
                cmap[src] = '?'
    return cmap

def extract(fname):
    data = load(fname)
    offs = object_offsets(data)
    pageobj = None
    for n, off in offs.items():
        body = data[off:off + 400]
        if re.match(rb'\s*<<\s*/Type /Page/', body) or re.match(rb'\s*<<\s*/Type/Page/', body):
            pageobj = n
            break
    pagestart = offs[pageobj]
    pageend = data.find(b'endobj', pagestart)
    pagebody = data[pagestart:pageend]
    contents = int(re.search(rb'/Contents (\d+) 0 R', pagebody).group(1))
    content = stream_from(data, contents)
    ctext = content.decode('latin-1')
    # resources
    resources = int(re.search(rb'/Resources (\d+) 0 R', pagebody).group(1))
    rstart = offs[resources]
    rbody = data[rstart:data.find(b'endobj', rstart)]
    fontdict = int(re.search(rb'/Font (\d+) 0 R', rbody).group(1))
    fstart = offs[fontdict]
    fbody = data[fstart:data.find(b'endobj', fstart)]
    fontmap = {}
    for fm in re.finditer(rb'/(\w+) (\d+) 0 R', fbody):
        name, fnum = fm.group(1).decode(), int(fm.group(2))
        fs = offs[fnum]
        fb = data[fs:data.find(b'endobj', fs)]
        toum = re.search(rb'/ToUnicode (\d+) 0 R', fb)
        cmap = {}
        if toum:
            cmc = stream_from(data, int(toum.group(1)))
            cmap = parse_cmap(cmc)
        fontmap[name] = cmap
    # linear scan
    fontre = re.compile(r'/(\w+) [\d.]+ Tf')
    hexre = re.compile(r'<[0-9A-Fa-f]*>')
    tmre = re.compile(r'1 0 0 -1 ([\d.]+) ([\d.]+) Tm')
    i, n = 0, len(ctext)
    cur_font = None
    pending = []
    res = []
    lasty = None
    while i < n:
        c = ctext[i]
        if c == '/':
            m = fontre.match(ctext, i)
            if m:
                cur_font = m.group(1)
                i = m.end(); continue
            i += 1; continue
        if c == '<':
            m = hexre.match(ctext, i)
            cmap = fontmap.get(cur_font, {})
            hexs = m.group(0)[1:-1]
            s = ''
            for k in range(0, len(hexs) - len(hexs) % 4, 4):
                s += cmap.get(int(hexs[k:k+4], 16), '')
            pending.append(s)
            i = m.end(); continue
        if ctext.startswith('1 0 0 -1', i):
            m = tmre.match(ctext, i)
            if m:
                y = float(m.group(2))
                if pending:
                    res.append(''.join(pending)); pending = []
                if lasty is not None and abs(y - lasty) > 1:
                    res.append('\n')
                lasty = y
                i = m.end(); continue
        if c == ']':
            res.append(''.join(pending)); pending = []
            i += 1; continue
        i += 1
    if pending:
        res.append(''.join(pending))
    text = ''.join(res)
    lines = [re.sub(r'  +', ' ', l.strip()) for l in text.split('\n')]
    return '\n'.join(l for l in lines if l)

for f in sys.argv[1:]:
    print('=' * 20, f, '=' * 20)
    print(extract(f))
